def simulate_snake(board_size, snake, food, moves):
    """
    Simulates a snake game with given board size, snake position, food locations, and movement commands.

    Parameters:
        board_size (tuple): (width, height)
        snake (list): List of (x, y) tuples; head is first element.
        food (list): Ordered list of (x, y) tuples; only the first is "active".
        moves (list): List of direction strings: "UP", "DOWN", "LEFT", "RIGHT".

    Returns:
        tuple: (final_snake, alive, food_eaten)
    """
    width, height = board_size

    def is_valid_position(x, y):
        return 0 <= x < width and 0 <= y < height

    def get_new_head_position(head, direction):
        directions = {
            "UP": (head[0], head[1] - 1),
            "DOWN": (head[0], head[1] + 1),
            "LEFT": (head[0] - 1, head[1]),
            "RIGHT": (head[0] + 1, head[1])
        }
        return directions.get(direction, head)

    def check_collision(new_head, current_snake):
        if not is_valid_position(*new_head):
            return True  # Invalid position causes death
        if new_head in current_snake[:-1]:
            return True  # Collision with own body (excluding tail that moves away)
        return False

    current_snake = snake
    active_food_idx = 0
    food_eaten = 0
    alive = True
    previous_direction = None  # To detect opposite direction moves

    for move in moves:
        if not alive:
            break

        new_head = get_new_head_position(current_snake[0], move)
        head_was_just_moved = check_collision(new_head, current_snake)

        if not is_valid_position(*new_head):
            return (current_snake, False, food_eaten)

        # If previous move was opposite direction, keep current direction
        if previous_direction and move == opposite(previous_direction):
            new_head = get_new_head_position(current_snake[0], previous_direction)
            head_was_just_moved = check_collision(new_head, current_snake)

        # Update direction after applying valid move
        if move != "UP" or not is_valid_position(*get_new_head_position(current_snake[0], "DOWN")):
            previous_direction = move

        if head_was_just_moved:
            return (current_snake, False, food_eaten)

        current_snake.append(new_head)

        # Check food collision
        if active_food_idx < len(food):
            new_head_x, new_head_y = new_head
            if (new_head_x == food[active_food_idx][0] and new_head_y == food[active_food_idx][1]):
                food_eaten += 1
                current_snake.append(new_head)
                active_food_idx += 1

        # Remove tail unless snake just ate
        if active_food_idx < len(food):
            current_snake.pop()

    return (current_snake, alive, food_eaten)


def opposite(direction):
    opposites = {
        "UP": "DOWN",
        "DOWN": "UP",
        "LEFT": "RIGHT",
        "RIGHT": "LEFT"
    }
    return opposites.get(direction, direction)
